import Img1 from './banner2.jpeg';
import { Nav, Navbar, NavDropdown } from "react-bootstrap";
import Logo from "./four.png";
import './Home.css';
import 'bootstrap/dist/css/bootstrap.min.css';


function Home() {
  return (

    <Navbar collapseOnSelect expand="lg"  variant="dark">
      <Navbar.Brand href="#home">
        <font id='heading1'><img src={Logo} className='church-logo'/>Foursquare</font>
      </Navbar.Brand>
        <Nav i> 
          <Nav.Link href="#" id=''>HOME</Nav.Link>
          <Nav.Link href="#" id='navlink1'>ABOUT</Nav.Link>
          <Nav.Link href="#" id='navlink1' >SERVE</Nav.Link>
          <Nav.Link href="#" id='navlink1' >MEDIA</Nav.Link>
          <Nav.Link href="#" id='navlink1' >CONTANT US</Nav.Link>
        </Nav>
      </Navbar>

  );
}
export default Home;
